import { encryptChacha20poly1305, decryptChacha20poly1305 } from '@exodus/crypto/chacha'
import * as curve25519 from '@exodus/crypto/curve25519'
import { hash } from '@exodus/crypto/hash'
import { randomValues } from '@exodus/crypto/randomBytes'
import { xsalsa20poly1305 } from '@noble/ciphers/salsa'
import { assert, assertUint8, assertUint8AnySize } from './utils/assertUint8.mjs'
import { fromUint8Super } from './utils/output.mjs'
import {
  toUint8Array,
  utf8Buf,
  salsaNonceBytes,
  salsaKeyBytes,
  salsaMacBytes,
  salsaSharedSecret,
} from './utils/sodium.mjs'

// APIs compatible with https://npmjs.com/@exodus/sodium-crypto

export async function convertPublicKeyToX25519(publicKey) {
  return curve25519.edwardsToMontgomeryPublic({ publicKey: toUint8Array(publicKey) }) // uint8
}

export async function convertPrivateKeyToX25519(privateKey) {
  const privateKeyArr = toUint8Array(privateKey)
  assertUint8(privateKeyArr, 64)
  return curve25519.edwardsToMontgomeryPrivate({ privateKey: privateKeyArr.subarray(0, 32) }) // uint8
}

export async function genSignKeyPair(rawSeed) {
  const seed = toUint8Array(rawSeed)
  assertUint8(seed, 32)
  const publicKey = await curve25519.edwardsToPublic({ privateKey: seed, format: 'buffer' })
  const privateKey = Buffer.concat([seed, publicKey]) // sodium does that
  return { publicKey, privateKey, keyType: 'ed25519' }
}

export async function genBoxKeyPair(rawSeed) {
  const seed = toUint8Array(rawSeed)
  assertUint8(seed, 32)
  const privateKey = (await hash('sha512', seed, 'buffer')).subarray(0, 32)
  const publicKey = await curve25519.montgomeryToPublic({ privateKey, format: 'buffer' })
  return { publicKey, privateKey, curve: 'x25519' }
}

export async function getSodiumKeysFromSeed(rawSeed) {
  const seed = toUint8Array(rawSeed)
  assertUint8(seed, 32)
  const { curve: keyTypeBox, ...box } = await genBoxKeyPair(seed)
  return {
    box: { ...box, keyType: keyTypeBox },
    sign: await genSignKeyPair(seed),
    secret: await hash('blake2b256', seed, 'buffer'),
    derived: Buffer.from(seed), // copy
  }
}

export async function signDetached({ message, privateKey }) {
  assertUint8(privateKey, 64)
  return curve25519.signDetached({
    message,
    privateKey: privateKey.subarray(0, 32),
    format: 'buffer',
  })
}

export async function verifyDetached({ message, sig, publicKey }) {
  return curve25519.verifyDetached({ message, signature: sig, publicKey })
}

export async function sign({ message, privateKey }) {
  assertUint8(privateKey, 64)
  return curve25519.signAttached({
    message,
    privateKey: privateKey.subarray(0, 32),
    format: 'buffer',
  })
}

export async function signOpen({ signed, publicKey }) {
  return curve25519.signOpen({ signed, publicKey, format: 'buffer' })
}

// message, nonce and associatedData are uint8/utf8, key is uint8 (hex and utf are broken in @exodus/sodium-crypto)
export async function encryptAEAD(message, secretKey, nonce, associatedData = '') {
  return encryptChacha20poly1305({
    key: secretKey,
    data: utf8Buf(message),
    nonce: utf8Buf(nonce, 12),
    additionalData: utf8Buf(associatedData ?? ''),
    format: 'buffer',
  })
}

// ciphertext, nonce and associatedData are uint8/utf8, secretKey is uint8 (hex and utf are broken in @exodus/sodium-crypto)
export async function decryptAEAD(ciphertext, secretKey, nonce, associatedData = '') {
  return decryptChacha20poly1305({
    key: secretKey,
    data: utf8Buf(ciphertext),
    nonce: utf8Buf(nonce, 12),
    additionalData: utf8Buf(associatedData ?? ''),
    format: 'buffer',
  })
}

// message is uint8/utf8, secretKey is uint8/hex
export async function encryptSecret(message, secretKey) {
  const nonce = randomValues(salsaNonceBytes)
  const salsa = xsalsa20poly1305(toUint8Array(secretKey, 32), nonce)
  const input = utf8Buf(message)
  const ciphertext = salsa.encrypt(input)
  assertUint8(ciphertext, salsaMacBytes + input.length, 'output')
  return Buffer.concat([nonce, ciphertext])
}

// both arguments are uint8/hex
export async function decryptSecret(ciphertextWithNonce, secretKey) {
  const input = toUint8Array(ciphertextWithNonce)
  assert(input.length >= salsaNonceBytes + salsaMacBytes, 'Encrypted data too short')
  const nonce = input.subarray(0, salsaNonceBytes)
  const ciphertext = input.subarray(salsaNonceBytes)
  const salsa = xsalsa20poly1305(toUint8Array(secretKey, 32), nonce)
  const output = salsa.decrypt(ciphertext)
  assertUint8(output, input.length - salsaNonceBytes - salsaMacBytes, 'output')
  return fromUint8Super(output, 'buffer')
}

const salsaSecretFromKeys = async (privateKey, publicKey) =>
  salsaSharedSecret(await curve25519.getSharedSecretMontgomery({ privateKey, publicKey }))

// message is uint8/utf8, toPublic/fromPrivate are uint8/hex
export async function encryptBox(message, toPublic, fromPrivate) {
  const secretKey = await salsaSecretFromKeys(toUint8Array(fromPrivate), toUint8Array(toPublic))
  return encryptSecret(message, secretKey)
}

// input is uint8 (hex/utf broken in @exodus/sodium-crypto), toPublic/fromPrivate are uint8/hex
export async function decryptBox(input, fromPublic, toPrivate) {
  assertUint8AnySize(input)
  const secretKey = await salsaSecretFromKeys(toUint8Array(toPrivate), toUint8Array(fromPublic))
  return decryptSecret(input, secretKey)
}

// message is uint8/utf8, toPublic is uint8/hex
export async function encryptSealedBox(message, toPublic) {
  const toPublicKey = toUint8Array(toPublic, 32)
  const privateKey = randomValues(32)
  const publicKey = await curve25519.montgomeryToPublic({ privateKey })
  const nonce = await hash('blake2b192', [publicKey, toPublicKey], 'uint8')
  assertUint8(nonce, salsaNonceBytes)
  const secretKey = await salsaSecretFromKeys(privateKey, toPublicKey)
  const salsa = xsalsa20poly1305(secretKey, nonce)
  const input = utf8Buf(message)
  const ciphertext = salsa.encrypt(input)
  assertUint8(ciphertext, salsaMacBytes + input.length, 'output')
  return Buffer.concat([publicKey, ciphertext])
}

// input is uint8 (utf8 is broken in @exodus/sodium-crypto), toPublic/toPrivate are uint8/hex
export async function decryptSealedBox(input, toPublic, toPrivate) {
  assertUint8AnySize(input)
  assert(input.length >= salsaKeyBytes + salsaMacBytes, 'Encrypted data too short')
  const publicKey = input.subarray(0, salsaKeyBytes)
  const ciphertext = input.subarray(salsaKeyBytes)
  const nonce = await hash('blake2b192', [publicKey, toUint8Array(toPublic, 32)], 'uint8') // need to validate size here, as toPublic is not used anywhere else
  assertUint8(nonce, salsaNonceBytes)
  const secretKey = await salsaSecretFromKeys(toUint8Array(toPrivate), publicKey)
  const salsa = xsalsa20poly1305(secretKey, nonce)
  const output = salsa.decrypt(ciphertext)
  assertUint8(output, input.length - salsaKeyBytes - salsaMacBytes, 'output')
  return fromUint8Super(output, 'buffer')
}
